#define AA 2 // Anti-aliasing level; increase for smoother edges but at performance cost

float smin( float a, float b, float k )
{
    // Smooth minimum function for blending shapes; adjust 'k' for blending intensity
    float h = clamp( 0.5+0.5*(b-a)/k, 0.0, 1.0 );
    return mix( b, a, h ) - k*h*(1.0-h);
}

const int MAX_POINTS = 64; 
vec3 points[MAX_POINTS];

float sdf(vec3 p)
{
    // Signed Distance Function for blob; adjust the initial 'd' for background distance
    float d = 80.0; // Change this to adjust how far the blob extends from the center
    for(int i=0; i<8; i++) // Loop through 8 points; adjust this number to change the complexity of the blob
    {
        // Adjust 0.6 to change the size of each sphere; larger values make bigger spheres
        d = smin(d, length(p - points[i]) - 0.6, 0.8); // 0.8 is the blending factor; adjust for smoother or sharper transitions
    }
    return d;
}

vec3 hsv2rgb(vec3 c)
{

    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 col = vec3(0.0);
    for( int m=0; m<AA; m++ )
    for( int n=0; n<AA; n++ )
    {

        vec2 p = (fragCoord.xy+vec2(float(m),float(n))/float(AA)-iResolution.xy*.5)/iResolution.y;

        vec3 ro = vec3(0.0, 2.0, -3.0); // Ray origin; adjust to zoom in/out or change perspective
        vec3 ta = vec3(0.0, 0.0, 0.0); // Point the camera is looking at
        vec3 ww = normalize( ta - ro );
        vec3 uu = normalize( cross(ww,vec3(0.0,1.0,0.0)) );
        vec3 vv = normalize( cross(uu,ww));
        vec3 rd = normalize( p.x*uu + p.y*vv + 1.5*ww ); // Ray direction; 1.5 controls field of view

        float time = iTime * 0.5; // Speed of particle movement; adjust for faster/slower motion

        int numPoints = 16; // Number of active points; adjust for more/less complexity
        numPoints = clamp(numPoints, 1, MAX_POINTS);

        for(int i=0; i<numPoints; i++)
        {
            // Particle movement; modify these sine functions for different movement patterns
            points[i] = vec3(sin(time+float(i)), cos(time+float(i)), sin(time+2.0*float(i)));
        }

        float t = 0.0;
        float maxd = 10.0; 
        for( int i=0; i<64; i++ ) 
        {
            vec3 p = ro + rd*t;

            float d = sdf(p);

            if( d<0.001 || t>maxd ) break; 
            t += d;
        }

        vec3 colAA = vec3(0.0);
        if( t<maxd )
        {
            vec3 pos = ro + rd*t;
            vec3 nor = vec3(0.0);
            float eps = 0.001; 
            nor = normalize( vec3(
                sdf(pos + vec3(eps,0.0,0.0)) - sdf(pos),
                sdf(pos + vec3(0.0,eps,0.0)) - sdf(pos),
                sdf(pos + vec3(0.0,0.0,eps)) - sdf(pos)));

            vec3 lightDir = normalize(vec3(1.0, 1.0, -1.0)); // Light direction; adjust to change lighting
            float diff = max(dot(nor, lightDir), 0.0);
            vec3 reflectDir = reflect(-lightDir, nor);
            float spec = pow(max(dot(rd, reflectDir), 0.0), 32.0); // Specular power; higher for sharper highlights

            // Slow time variation for the spectrum; adjust 0.01 for faster/slower color shift
            float slowTime = iTime * 0.01;

            vec3 combinedColor = vec3(0.0);
            float totalInfluence = 0.0;
            for(int i=0; i<numPoints; i++)
            {
                float influence = 1.0 - smoothstep(0.0, 0.6, length(pos - points[i])); // Influence based on distance; 0.6 should match sphere radius in sdf
                if(influence > 0.0)
                {
                    float hue = fract(float(numPoints) / float(MAX_POINTS) + float(i) / float(numPoints) + slowTime);
                    vec3 sphereColor = hsv2rgb(vec3(hue, 1.0, 1.0)); // Full saturation and value; adjust for different color effects
                    combinedColor += sphereColor * influence;
                    totalInfluence += influence;
                }
            }
            vec3 diffuseColor = combinedColor / max(totalInfluence, 0.001);


            colAA = (diff * diffuseColor + vec3(0.2) * spec);
        }

        col += colAA;
    }
    col /= float(AA*AA);

    fragColor = vec4( col, 1.0 );
}
